import Redwood from 'redwood'
const client = new Redwood()
// defaults -> RetryPolicy.DEFAULT
const resp = await client.generate({ prompt: 'Hi', idempotencyKey: 'ts-req-77' })

// streaming: pre-first-frame retry allowed
const stream = client.streamGenerate({ prompt: 'Long...', idempotencyKey: 'ts-stream-3'} )
stream.on('data', chunk => {
  // after first chunk, SDK won't auto-retry
})
// resume token example (server must support it)
await stream.resume(resumeToken)

